// n8n Code node
// Mode: Run Once for All Items
// Place immediately before the Langfuse HTTP Request node.

const VERSION = '1.4.1';
const MAX_EVIDENCE_CHARS = 30000;
const MAX_UINT64 = 18446744073709551615n;

function buildOtelBody(j) {
  const present = (v) =>
    v !== undefined &&
    v !== null &&
    !(typeof v === 'string' && v.trim() === '');

  const asText = (v) =>
    typeof v === 'string' ? v : JSON.stringify(v);

  const str = (key, value) => ({
    key,
    value: { stringValue: String(value) },
  });

  const integer = (key, value) => ({
    key,
    value: { intValue: String(value) },
  });

  const attrs = [];

  const put = (key, value) => {
    if (!present(value)) return;
    const valueText = asText(value);
    if (valueText !== undefined) {
      attrs.push(str(key, valueText));
    }
  };

  const meta = (key, value) =>
    put(`langfuse.observation.metadata.${key}`, value);

  const traceMeta = (key, value) =>
    put(`langfuse.trace.metadata.${key}`, value);

  const hexId = (value, length, label) => {
    const id = String(value ?? '').trim().toLowerCase();

    if (
      !new RegExp(`^[0-9a-f]{${length}}$`).test(id) ||
      /^0+$/.test(id)
    ) {
      throw new Error(
        `${label} must be a nonzero ${length}-character hex ID`
      );
    }

    return id;
  };

  const nanoTime = (value, label) => {
    if (!present(value)) return null;

    const valueText = String(value).trim();

    if (!/^\d{1,20}$/.test(valueText)) {
      throw new Error(
        `${label} must contain only nanosecond timestamp digits`
      );
    }

    const valueBigInt = BigInt(valueText);

    if (valueBigInt <= 0n || valueBigInt > MAX_UINT64) {
      throw new Error(`${label} is outside the uint64 range`);
    }

    return valueText;
  };

  const tokenCount = (value, label) => {
    if (!present(value)) return null;

    const number = Number(value);

    if (!Number.isSafeInteger(number) || number < 0) {
      throw new Error(`${label} must be a nonnegative integer`);
    }

    return number;
  };

  const traceId = hexId(j.trace_id, 32, 'trace_id');
  const spanId = hexId(j.span_id, 16, 'span_id');

  const parentSpanId = present(j.parent_span_id)
    ? hexId(j.parent_span_id, 16, 'parent_span_id')
    : null;

  if (parentSpanId === spanId) {
    throw new Error('parent_span_id cannot equal span_id');
  }

  const nowNs = `${Date.now()}000000`;

  const startTime =
    nanoTime(j.start_time_ns, 'start_time_ns') ?? nowNs;

  const endTime =
    nanoTime(j.end_time_ns, 'end_time_ns') ?? nowNs;

  if (BigInt(endTime) < BigInt(startTime)) {
    throw new Error('end_time_ns precedes start_time_ns');
  }

  const workflowName = present(j.workflow_name)
    ? String(j.workflow_name)
    : 'mira';

  const allowedTypes = new Set([
    'span',
    'generation',
    'event',
    'embedding',
    'agent',
    'tool',
    'chain',
    'retriever',
    'guardrail',
    'evaluator',
  ]);

  // An agent may make several model calls, so its aggregate
  // workflow observation is not automatically one generation.
  const inferredType = /agent/i.test(workflowName)
    ? 'agent'
    : 'span';

  const observationType = present(j.observation_type)
    ? String(j.observation_type).trim().toLowerCase()
    : inferredType;

  if (!allowedTypes.has(observationType)) {
    throw new Error(
      `Unsupported observation_type: ${observationType}`
    );
  }

  const statusText = String(j.status ?? '')
    .trim()
    .toLowerCase();

  const failed = [
    'error',
    'failed',
    'failure',
  ].includes(statusText);

  // Detect an entire n8n expression accidentally passed as text.
  const unresolved = (value) =>
    typeof value === 'string' &&
    /^\s*\{\{[\s\S]*\}\}\s*$/.test(value);

  const inputUnresolved = unresolved(j.input);
  const outputUnresolved = unresolved(j.output);

  put('langfuse.observation.type', observationType);
  put('langfuse.trace.name', workflowName);

  traceMeta('workflow_name', workflowName);
  traceMeta('exporter_version', VERSION);
  traceMeta('status', j.status);
  traceMeta('project_id', j.project_id);
  traceMeta('snapshot_id', j.snapshot_id);
  traceMeta('test_case_id', j.test_case_id);

  meta('exporter_version', VERSION);
  meta('status', j.status);
  meta('project_id', j.project_id);
  meta('snapshot_id', j.snapshot_id);
  meta('test_case_id', j.test_case_id);

  for (const key of [
    'request_type',
    'capability',
    'quality_criterion',
    'expected_behavior',
    'source_references',
    'validation_status',
    'grounding_status',
    'grounding_verified',
    'citation_coverage_pct',
    'error_detail',
    'prompt_version',
    'schema_version',
    'retrieval_summary',
    'execution_id',
    'tool_summary',
    'evaluator_verdict',
    'evaluator_reason',
    'evaluation_version',
  ]) {
    meta(key, j[key]);
  }

  meta(
    'quality_criterion_available',
    present(j.quality_criterion)
  );

  const sessionId = present(j.session_id)
    ? j.session_id
    : j.project_id;

  put('langfuse.session.id', sessionId);
  put('langfuse.user.id', j.user_id);

  if (!inputUnresolved) {
    put('langfuse.observation.input', j.input);
  }

  if (!outputUnresolved) {
    put('langfuse.observation.output', j.output);
  }

  meta('input_unresolved_expression', inputUnresolved);
  meta('output_unresolved_expression', outputUnresolved);
  meta(
    'output_available',
    present(j.output) && !outputUnresolved
  );

  // Evidence is opt-in because it may be large or sensitive.
  if (
    j.export_source_evidence === true &&
    present(j.source_evidence)
  ) {
    const evidence = asText(j.source_evidence);

    if (evidence.length <= MAX_EVIDENCE_CHARS) {
      meta('source_evidence', evidence);
      meta('source_evidence_exported', true);
    } else {
      meta('source_evidence_exported', false);
      meta(
        'source_evidence_export_reason',
        'exceeds_size_limit'
      );
    }
  } else {
    meta('source_evidence_exported', false);
  }

  if (present(j.model)) {
    meta('model_name', j.model);

    if (
      observationType === 'generation' ||
      observationType === 'embedding'
    ) {
      put('langfuse.observation.model.name', j.model);
      put('gen_ai.request.model', j.model);
    }
  }

  const inputTokens = tokenCount(
    j.input_tokens,
    'input_tokens'
  );

  const outputTokens = tokenCount(
    j.output_tokens,
    'output_tokens'
  );

  if (
    observationType === 'generation' ||
    observationType === 'embedding'
  ) {
    if (inputTokens !== null) {
      attrs.push(
        integer('gen_ai.usage.input_tokens', inputTokens)
      );
    }

    if (outputTokens !== null) {
      attrs.push(
        integer('gen_ai.usage.output_tokens', outputTokens)
      );
    }
  } else {
    // Keep agent-level totals informational, avoiding duplicate
    // generation usage if child model calls are also exported.
    meta('aggregate_input_tokens', inputTokens);
    meta('aggregate_output_tokens', outputTokens);
  }

  const warning = inputUnresolved || outputUnresolved;

  const message = failed
    ? String(j.error_detail ?? j.status ?? 'Execution failed')
    : warning
      ? 'Unresolved n8n expression omitted from observation'
      : null;

  if (failed) {
    put('langfuse.observation.level', 'ERROR');
    put('langfuse.observation.status_message', message);
  } else if (warning) {
    put('langfuse.observation.level', 'WARNING');
    put('langfuse.observation.status_message', message);
  }

  const span = {
    traceId,
    spanId,
    name: workflowName,
    kind: 1,
    startTimeUnixNano: startTime,
    endTimeUnixNano: endTime,
    attributes: attrs,
    status: failed
      ? { code: 2, message }
      : { code: 1 },
  };

  if (parentSpanId) {
    span.parentSpanId = parentSpanId;
  }

  return {
    resourceSpans: [
      {
        resource: {
          attributes: [
            str(
              'service.name',
              present(j.service_name)
                ? j.service_name
                : 'mira-agents'
            ),
          ],
        },
        scopeSpans: [
          {
            scope: {
              name: 'n8n-mira',
              version: VERSION,
            },
            spans: [span],
          },
        ],
      },
    ],
  };
}

return $input.all().map((item) => ({
  json: {
    otel_body: buildOtelBody(item.json),
  },
}));
